/* 학습 해설
 * DTB reserve splice·entry 단위와 두 base 이동
 * DTB 가변 수정의 block 배치, tail splice와 metadata, 이름 재사용/원복, 예약·property·node 수정, packing과 format 변환의 원리를 읽습니다.
 * oldn/newn entry 수에 sizeof(entry)를 곱해 byte splice를 요청합니다. 성공이면 delta=(newn−oldn)*16을 structure와 strings 시작 offset에 더합니다. structure-relative node offset은 같은 자료 안에서 유지될 수 있지만 absolute pointer는 block 이동 때문에 달라집니다.
 * 예약 entry 추가/삭제 뒤 두 block base가16 늘거나 줄어드는 값을 계산합니다. relative 위치와 기존 pointer 보존을 서로 다른 조건으로 읽습니다.
 */
static int fdt_splice_mem_rsv_(void *fdt, struct fdt_reserve_entry *p,
			       int oldn, int newn)
{
	int delta = (newn - oldn) * sizeof(*p);
	int err;
	err = fdt_splice_(fdt, p, oldn * sizeof(*p), newn * sizeof(*p));
	if (err)
		return err;
	fdt_set_off_dt_struct(fdt, fdt_off_dt_struct(fdt) + delta);
	fdt_set_off_dt_strings(fdt, fdt_off_dt_strings(fdt) + delta);
	return 0;
}

static int fdt_splice_struct_(void *fdt, void *p,
			      int oldlen, int newlen)
{
	int delta = newlen - oldlen;
	int err;

	if ((err = fdt_splice_(fdt, p, oldlen, newlen)))
		return err;

	fdt_set_size_dt_struct(fdt, fdt_size_dt_struct(fdt) + delta);
	fdt_set_off_dt_strings(fdt, fdt_off_dt_strings(fdt) + delta);
	return 0;
}

