annotated:
/* 학습 해설
 * DTB read-write 이름 dedup·정상 nonnegative offset
 * DTB 가변 수정의 block 배치, tail splice와 metadata, 이름 재사용/원복, 예약·property·node 수정, packing과 format 변환의 원리를 읽습니다.
 * 기존 table에서 NUL byte sequence를 찾으면 시작 기준 offset을 반환합니다. 없으면 끝에 공간을 확보하고 이름을 복사합니다. NO_ROLLBACK 전제가 없을 때 allocated0/1을 기록하며 이 값은 뒤 property 공간 실패의 원복에 사용됩니다. 기존 이름의 suffix도 재사용 가능할 수 있습니다.
 * 정상 offset0도 성공이며 sequential 내부 helper의0 실패 sentinel과 다름을 적습니다. 이름 추가 오류는 음수인 이 helper의 계약을 비교합니다.
 */
static int fdt_find_add_string_(void *fdt, const char *s, int *allocated)
{
	char *strtab = (char *)fdt + fdt_off_dt_strings(fdt);
	const char *p;
	char *new;
	int len = strlen(s) + 1;
	int err;

	if (!can_assume(NO_ROLLBACK))
		*allocated = 0;

	p = fdt_find_string_(strtab, fdt_size_dt_strings(fdt), s);
	if (p)
		/* found it */
		return (p - strtab);

	new = strtab + fdt_size_dt_strings(fdt);
	err = fdt_splice_string_(fdt, len);
	if (err)
		return err;

	if (!can_assume(NO_ROLLBACK))
		*allocated = 1;

	memcpy(new, s, len);
	return (new - strtab);

