/* 학습 해설
 * DTB 예약 추가·terminator 앞 삽입
 * DTB 가변 수정의 block 배치, tail splice와 metadata, 이름 재사용/원복, 예약·property·node 수정, packing과 format 변환의 원리를 읽습니다.
 * reserve 개수를 얻고 그 위치의 terminator 앞에 entry 한 개를 splice합니다. 뒤 structure/strings를 밀고 주소·크기를 big-endian64로 기록합니다. terminator를 덮어 없애는 단순 overwrite가 아니라 기존 종료 표시를 뒤로 보존하는 삽입입니다.
 * 두 예약을 실제 추가해 num2를 얻습니다. tree 자료의 예약 목록 수정과 실제 OS allocator에 예약을 적용하는 것은 다른 단계라고 적습니다.
 */
int fdt_add_mem_rsv(void *fdt, uint64_t address, uint64_t size)
{
	struct fdt_reserve_entry *re;
	int err;

	FDT_RW_PROBE(fdt);

	re = fdt_mem_rsv_w_(fdt, fdt_num_mem_rsv(fdt));
	err = fdt_splice_mem_rsv_(fdt, re, 0, 1);
	if (err)
		return err;

	re->address = cpu_to_fdt64(address);
	re->size = cpu_to_fdt64(size);
	return 0;
}

int fdt_del_mem_rsv(void *fdt, int n)
{
	struct fdt_reserve_entry *re = fdt_mem_rsv_w_(fdt, n);

	FDT_RW_PROBE(fdt);

	if (n >= fdt_num_mem_rsv(fdt))
		return -FDT_ERR_NOTFOUND;

