/* 학습 해설
 * DTB 새 property·node header 뒤 삽입과 이름 원복
 * DTB 가변 수정의 block 배치, tail splice와 metadata, 이름 재사용/원복, 예약·property·node 수정, packing과 format 변환의 원리를 읽습니다.
 * node checker로 header 뒤 위치를 얻고 이름을 찾거나 추가합니다. 그 위치에 property header12+정렬 value 공간을 삽입합니다. 실패하면 기본 문맥에서 새 이름만 원복하고 성공이면 tag/nameoff/len을 씁니다. 새 property는 node property 목록 앞에 들어갈 수 있어 순서가 기존과 달라집니다.
 * 새 empty property를 실제 추가하고 len0이어도 header가 필요함을 계산합니다. 전체 tree를 재배치한 뒤 기존 offset 사용과 이름 path 재조회 조건을 읽습니다.
 */
static int fdt_add_property_(void *fdt, int nodeoffset, const char *name,
			     int len, struct fdt_property **prop)
{
	int proplen;
	int nextoffset;
	int namestroff;
	int err;
	int allocated;

	if ((nextoffset = fdt_check_node_offset_(fdt, nodeoffset)) < 0)
		return nextoffset;

	namestroff = fdt_find_add_string_(fdt, name, &allocated);
	if (namestroff < 0)
		return namestroff;

	*prop = fdt_offset_ptr_w_(fdt, nextoffset);
	proplen = sizeof(**prop) + FDT_TAGALIGN(len);

	err = fdt_splice_struct_(fdt, *prop, 0, proplen);
	if (err) {
		/* Delete the string if we failed to add it */
		if (!can_assume(NO_ROLLBACK) && allocated)
			fdt_del_last_string_(fdt, name);
		return err;
	}

